'use strict';
// Final retrospective pages. Keep earlier dataset views reproducible.
const priorHistoryOverview=historyOverview, priorSegmentationAnalysis=customerSegmentationAnalysis,
 priorMarketValueAnalysis=marketValueAnalysis, priorWaccImpactAnalysis=waccImpactAnalysis;
const finalList=items=>`<ul class="review-copy">${items.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`;
const finalDownload=(endpoint,label='↓ Download analysis HTML')=>offline?'':`<a class="button" href="${endpoint}" download>${label}</a>`;
const fixed=(v,n=3)=>v===null||v===undefined?'—':Number(v).toFixed(n);
// Actual-versus-fitted scatter with a 45° reference line. No fitted value is hidden.
function fitScatter(predictions,format,color='#7c3aed',opts={}){
 const width=opts.width||360,height=opts.height||260,left=54,right=16,top=18,bottom=42;
 const vals=predictions.flatMap(p=>[p.actual,p.fitted]).filter(Number.isFinite);
 if(!vals.length)return '';
 let lo=Math.min(...vals),hi=Math.max(...vals);
 if(lo===hi){lo-=.5;hi+=.5;}
 const pad=(hi-lo)*.12,min=lo-pad,max=hi+pad;
 const x=v=>left+(v-min)/(max-min)*(width-left-right);
 const y=v=>height-bottom-(v-min)/(max-min)*(height-top-bottom);
 let out=`<div class="review-chart fit-scatter"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(opts.label||'Actual versus fitted values')}">`;
 for(let i=0;i<=3;i++){const v=min+(max-min)*i/3;out+=`<line class="grid" x1="${left}" x2="${width-right}" y1="${y(v)}" y2="${y(v)}"/><text x="${left-7}" y="${y(v)+4}" text-anchor="end">${esc(format(v))}</text>`;}
 out+=`<line x1="${x(min)}" y1="${y(min)}" x2="${x(max)}" y2="${y(max)}" stroke="#94a3b8" stroke-width="1.5" stroke-dasharray="5 4"/>`;
 predictions.forEach(p=>{
  if(!Number.isFinite(p.actual)||!Number.isFinite(p.fitted))return;
  const cx=x(p.actual),cy=y(p.fitted),nearRight=cx>width-right-42,dx=nearRight?-7:7,dy=p.round%2===0?-8:15;
  out+=`<circle cx="${cx.toFixed(1)}" cy="${cy.toFixed(1)}" r="4.5" fill="${color}" fill-opacity=".9"><title>R${p.round}: actual ${esc(format(p.actual))}, fitted ${esc(format(p.fitted))}</title></circle><text x="${(cx+dx).toFixed(1)}" y="${(cy+dy).toFixed(1)}" text-anchor="${nearRight?'end':'start'}" class="chart-value">R${p.round}</text>`;
 });
 out+=`<line x1="${left}" x2="${width-right}" y1="${height-bottom}" y2="${height-bottom}" stroke="#cbd5e1"/><line x1="${left}" x2="${left}" y1="${top}" y2="${height-bottom}" stroke="#cbd5e1"/>`;
 out+=`<text x="${(left+width-right)/2}" y="${height-12}" text-anchor="middle">Reported actual</text><text x="12" y="${(top+height-bottom)/2}" text-anchor="middle" transform="rotate(-90 12 ${(top+height-bottom)/2})">Fitted</text>`;
 return out+'</svg></div>';
}
function finalSubmittedDecisions(){return head('SIMULATION COMPLETE · SUBMITTED R8 WORKBOOK','Final submitted decisions','Actual decision 8 compared with decision 7. This is a historical record, not a proposed new allocation.')+panel('All 16 submitted inputs','No workbook is edited by this review.',currentChangesTable())+sources();}
function finalObjectiveTable(){const r=data.final_review;return table(['Objective','Final score / rank','Leader','CSV fair value','Result'],r.objectives.map(v=>[esc(v.quadrant)+(v.quadrant==='EXPERIENCE'?' · #1':v.quadrant==='BRAND'?' · top two':' · parity'),`${num(v.score)} / #${v.rank}`,num(v.leader),num(v.fair_value),v.target_met?'Met':`${num(v.target_gap)} below target`]))+`<p class="review-copy">Experience first reached #1 in R${r.experience_leader_rounds[0]}. Frictionless was below the exported floor in ${r.frictionless_below_floor_rounds.length} of ${r.scored_rounds.length} scored rounds. Fair value is the reported CSV series, not 75% of the leader.</p>`;}
function executiveObjectiveTimeline(){
  const r=data.final_review,baseline=data.history_analysis.history.find(x=>x.round===0),h=data.history_analysis.history.filter(x=>x.round>0);
 const goals=[['EXPERIENCE','Experience · #1'],['BRAND','Brand · top two'],['FRICTIONLESS','Frictionless · fair value'],['LOW PRICE','Low Price · fair value']];
  return panel('Did we deliver throughout the run—or only at the finish?','Objective-delivery timeline · R0 baseline shown for context; only R1–R8 count toward rounds met.',
  `<div id="exec-objective-timeline">${table(['Objective','R0 baseline',...h.map(x=>'R'+x.round),'Rounds met'],goals.map(([q,label])=>[
  esc(label),num(baseline.quadrants[q].score)+'<br>'+(['EXPERIENCE','BRAND'].includes(q)?'Rank #'+baseline.quadrants[q].rank:signed(baseline.quadrants[q].gap)+' gap'),...h.map(row=>{const v=row.quadrants[q],detail=['EXPERIENCE','BRAND'].includes(q)?'Rank #'+v.rank:signed(v.gap)+' gap';return `<span class="review-badge ${v.target_met?'':'muted'}"><strong>${v.target_met?'Met':'Miss'}</strong><br>${detail}</span>`;}),`<strong>${h.filter(x=>x.quadrants[q].target_met).length}/${h.length}</strong>`]),'exec-objective-grid')}</div>`+
 note('Experience leadership was achieved only in R8; Brand passed in 6/8 rounds, Low Price in 8/8, and Frictionless in 0/8. No scored round met all four objectives. Rank goals compare the six actual competitors; parity gap = score minus that round’s exported FAIR VALUE. Low Price rank is not its success criterion.'));
}
function executiveGrowthPlots(){
 const r=data.final_review,s=r.segmentation_strategy;
 if(!s)return '';
 const core=s.groups[0],rounds=core.history.map(x=>x.round);
 return `<div class="review-grid executive-plot-grid">`+
  panel('Target mix: modest gains led by S6','S3+S6 combined · revenue and aggregate-CLV shares use separate company totals.',
  `<div id="exec-target-mix-chart">${historyLine('S3+S6 share of company revenue and aggregate CLV · R0–R8',rounds,[{label:'Revenue mix',values:core.history.map(x=>x.mix),color:'#7c3aed'},{label:'Aggregate-CLV mix',values:core.history.map(x=>x.clv_mix),color:'#0891b2'}],pct,false)}</div>`+
  note(`Revenue mix ${pct(core.initial_mix)} → ${pct(core.mix)}; CLV mix ${pct(core.initial_clv_mix)} → ${pct(core.clv_mix)}. Combined mix gains mask S3’s decline and S6’s increase. These are not segment market shares or per-customer CLV.`))+
 panel('Who supplied growth relative to their starting weight?','R0 revenue mix versus share of the total R0→R8 revenue increase.',
 `<div id="exec-growth-chart">${bars(s.groups.map(x=>({label:x.label.split(' · ')[0],values:[100*x.initial_mix,100*x.growth_share]})),{title:'Starting revenue mix versus contribution to revenue growth by strategy tier',format:v=>fixed(v,1)+'%',series:['R0 revenue mix','Share of revenue increase'],palette:['#94a3b8','#7c3aed']})}</div>`+
 note(`Targets contributed ${pct(core.growth_share)} of revenue growth versus ${pct(core.initial_mix)} of starting sales; S1 contributed ${pct(s.groups[2].growth_share)} versus ${pct(s.groups[2].initial_mix)}. This is a composition comparison—not marketing ROI, profit contribution or a reason to suppress non-target sales.`))+`</div>`;
}
function executiveFinancePlots(){
 const h=data.history_analysis.history,rounds=h.map(x=>x.round),first=h[0],last=h.at(-1),r6=h.find(x=>x.round===6);
 const chart=(id,title,key,format,color)=>`<article class="executive-finance-card"><h3>${title}</h3><div id="${id}">${historyLine(title+' · reported R0–R8',rounds,[{label:'Reported actual',values:h.map(x=>x[key]),color}],format,false)}</div><p class="review-copy">R0 ${format(first[key])} → R6 ${format(r6[key])} → R8 ${format(last[key])}</p></article>`;
 return panel('Financial recovery and financing pressure: separate the stories','Reported outcomes, not model predictions. Each panel has its own labeled units and scale; do not compare line slopes across panels.',
 `<div class="executive-finance-grid">`+
 chart('exec-value-chart','Market value · $','market_value',money,'#7c3aed')+
  chart('exec-income-chart','Net income · $','net_income',money,'#0891b2')+
  chart('exec-clv-chart','Aggregate customer lifetime value · $','clv',money,'#2563eb')+
 chart('exec-debt-chart','Interest-bearing debt · $','debt',money,'#d97706')+
 chart('exec-wacc-chart','WACC · %','wacc',v=>fixed(v,1)+'%','#64748b')+
 `</div>`+note(`Market value and earnings recovered while WACC finished ${num(last.wacc-first.wacc)} pp above R0. Debt remained below its starting level but increased ${money(last.debt-r6.debt)} after R6. Co-movement does not identify a causal earnings, borrowing or marketing-spend effect on value.`));
}
historyOverview=function(embed=false){if(!data.final_review)return priorHistoryOverview();const r=data.final_review,f=r.finance,h=data.history_analysis.history,first=h[0],last=h.at(-1),core=r.core;
  return (embed?'':head('FINAL RESULTS · R1–R8 + R0 BASELINE','Executive overview','Marketing-led review of the team-confirmed Segment 3 primary / Segment 6 secondary strategy and the financial outcome.',finalDownload('/final-report','↓ Download combined report')))+
 `<div class="review-hero"><div><div class="eyebrow">TWO DIFFERENTIATORS WON · CONVENIENCE REMAINS UNFINISHED</div><h2>Experience #1. Brand #1.<br>Late execution, incomplete parity.</h2><p>${esc(r.conclusion)}</p></div><div class="hero-aside">Final objectives met<strong>${r.objectives_met} / 4</strong>Experience 6.6 · Brand 6.0<br>Frictionless 3.9 vs 4.6 floor<br>Simulation complete; R0 baseline retained.</div></div>`+
  `<div class="cards">${card('FINAL MARKET VALUE',money(f.market_value),signed(f.value_growth,pct)+' since R0')}${card('CUSTOMER LIFETIME VALUE',money(last.clv),money(first.clv)+' R0 baseline · '+signed(last.clv/first.clv-1,pct))}${card('S3 + S6 REVENUE MIX',pct(core.mix),signed(core.mix_change_pp)+' pp since R0')}${card('FINAL UNIT SHARE',pct(f.unit_share),pct(f.initial_unit_share)+' at R0; reported scorecard')}${card('FINAL NET INCOME',money(f.net_income),money(f.initial_net_income)+' at R0')}</div>`+
  panel('Customer lifetime value: R0 baseline to R8 final','Aggregate customer equity—not CLV per customer.',`<p>Customer lifetime value rose from <strong>${money(first.clv)} in R0</strong> to <strong>${money(last.clv)} in R8</strong>, an increase of <strong>${pct(last.clv/first.clv-1)}</strong> (${fixed(last.clv/first.clv,2)}× the baseline). This is a reported outcome, not an isolated estimate of the strategy’s causal effect.</p>`)+
 panel('Marketing verdict: final differentiators achieved; delivery incomplete','Assess the original objectives, not just the market-value outcome.',finalObjectiveTable())+
 executiveObjectiveTimeline()+
  (r.objective_delivery?finalVerdictPanels():`<div class="review-grid">${panel('Where we did well','Realized marketing outcomes.',finalList(r.marketing_wins))}${panel('Where we fell short','The unfinished parts of the S3 + S6 strategy.',finalList(r.marketing_misses))}</div>`)+
  panel('Target growth: S6 broadened the Brand-led core','Company revenue mix—not segment market share or measured marketing ROI.',`<p>S3+S6 finish at <strong>${money(core.revenue)}</strong>, ${pct(core.mix)} of company revenue and ${pct(core.clv_mix)} of aggregate CLV. Their revenue mix rose <strong>${num(core.mix_change_pp)} pp</strong>; CLV mix rose <strong>${num(core.clv_mix_change_pp)} pp</strong>. They supplied ${pct(core.growth_share)} of the R0→R8 revenue increase. S6’s mix gains outweighed S3’s decline. S1—not an acquisition priority—remained the largest revenue and customer-equity pool.</p><p class="review-copy">Late recovery matters: S3+S6 revenue grew ${pct(core.late_growth)} from R6 to R8. That is encouraging execution evidence, not proof that the full strategy drove incremental profit.</p><a href="#segmentation">Review the S3 + S6 scorecard →</a>`)+
 executiveGrowthPlots()+
 panel('Finance: a strong recovery, not a lower-WACC story','Earnings and capital discipline improved materially; late expansion resumed borrowing.',table(['Metric','R0 baseline','R8 final'],[['Revenue',money(first.revenue),money(f.revenue)],['EBIT',money(first.ebit),money(f.ebit)],['Net income',money(first.net_income),money(f.net_income)],['Gross margin',pct(first.gross_margin),pct(f.gross_margin)],['Debt',money(first.debt),money(f.debt)],['WACC',num(first.wacc)+'%',num(f.wacc)+'%']])+`<p class="review-copy">Market value reached ${money(f.market_value)} while WACC ended ${num(f.wacc_change_pp)} pp above R0. The recovery was not driven by a falling reported discount rate. Debt is below the starting level, but rose ${money(f.late_debt_change)} after R6 as stores expanded from ${num(f.late_stores)} to ${num(f.stores)}. Revenue share is ${pct(f.revenue_share)}, while unit share remains below its starting level: better price/mix economics did not establish volume dominance.</p>`)+
 executiveFinancePlots()+
 panel('The lesson to carry forward','Marketing priorities, with funding discipline.',finalList(r.lessons))+
 `<details class="panel"><summary>Full quadrant history · all reported floors</summary>${historyGapCharts()}</details>`+(embed?'':sources());};

customerSegmentationAnalysis=function(embed=false){
  return data.final_review?.segmentation_strategy?segmentationStrategyReview(embed):priorSegmentationAnalysis();
};

function segmentationStrategyReview(embed=false){
 const review=data.final_review,a=data.history_analysis,s=review.segmentation_strategy;
  const [core,support,other]=s.groups,[s3,s6,s2,s4,s5]=s.rows,h=a.history,rounds=h.map(x=>x.round);
 const at=n=>h.find(x=>x.round===n),segment=id=>a.segments.find(x=>x.id===id);
 const series=(label,values,color,dashed=false)=>({label,values,color,dashed});
 const wrap=text=>`<div class="wrap">${text}</div>`;
 const phaseLabels=['R0–R2 · early','R2–R6 · middle','R6–R8 · repair'];
 const scoreSeries=q=>h.map(x=>x.quadrants[q].score);
 const positionSeries=k=>h.map(x=>x.positions[k]);
 const spendSeries=k=>h.map(x=>x.decisions[k]);
 const targetLate=core.history.at(-1).revenue/core.history.find(x=>x.round===6).revenue-1;
 const targetMiddle=core.history.find(x=>x.round===6).revenue/core.history.find(x=>x.round===2).revenue-1;
 const needKeys=['BRAND','SHOPPING EXPERIENCE','CUSTOMER SERVICE','ONLINE','RETAIL','LOW PRICE','BREADTH','DEPTH'];
 const maxNeed=Math.max(...a.segments.flatMap(x=>needKeys.map(k=>x.preferences[k]||0)));
 const heat=v=>`<span class="heat-cell" style="background:rgba(124,58,237,${(v/maxNeed*.85).toFixed(2)});color:${v/maxNeed>.6?'#fff':'#35426b'}">${fixed(v,2)}</span>`;
  const headline=`S3 anchored the differentiated Brand/Experience offer; S6 extended its reach to Experience/value shoppers. S6 gained revenue mix while S3 lost a little, lifting the combined target mix. Supporting segments supplied ${pct(support.growth_share)} of the revenue increase; growth remained a portfolio result, not proof of causal targeting returns.`;
  return (embed?'':head('STRATEGY AUDIT · R0 BASELINE TO R8 FINAL','Customer segmentation analysis','Team-confirmed priority order: Segment 3 → Segment 6. Segments 2, 4 and 5 are shown as the supporting portfolio; S1 is outside the acquisition priorities.',finalDownload('/customer-segmentation-analysis')))+
  panel('S6 added growth beyond the Brand-led core','Recalculated against the team-confirmed S3-primary / S6-secondary strategy.',`<p class="seg-verdict">${headline}</p><p>S3+S6 revenue rose <strong>${pct(core.revenue_growth)}</strong> versus <strong>${pct(s.company_growth)}</strong> for Getchell’s. Their mix increased from ${pct(core.initial_mix)} to ${pct(core.mix)} (${signed(core.mix_change_pp)} pp), and aggregate-CLV mix rose from ${pct(core.initial_clv_mix)} to ${pct(core.clv_mix)}. This supports the growth rationale for S6, but does not establish segment profitability or an optimal target order.</p>`)+
  `<div class="cards">${card('S3 · PRIMARY',pct(s3.revenue_growth)+' growth',signed(s3.mix_change_pp)+' pp revenue mix')}${card('S6 · SECONDARY',pct(s6.revenue_growth)+' growth',signed(s6.mix_change_pp)+' pp revenue mix')}${card('SUPPORTING S2 / S4 / S5',pct(support.growth_share),'Share of company revenue increase')}${card('TARGET CLV GROWTH',pct(core.clv_growth),pct(core.clv_growth_share)+' of aggregate-CLV increase')}</div>`+
  panel('1 · Did outcomes match our priorities?','S3 first, S6 second. S2/S4/S5 form a comparison portfolio, not a newly inferred acquisition ranking.',
 table(['Priority / segment','R8 revenue','Added since R0','Revenue growth','Revenue mix R0 → R8','Mix Δ (pp)','CLV growth'],s.rows.map(x=>[esc(x.label),money(x.revenue),money(x.incremental_revenue),pct(x.revenue_growth),pct(x.initial_mix)+' → '+pct(x.mix),signed(x.mix_change_pp),pct(x.clv_growth)]))+
  note(`S6 gained ${num(s6.mix_change_pp)} pp of revenue mix, outweighing S3’s ${num(-s3.mix_change_pp)} pp decline. At unchanged R0 mix, S3+S6 would represent ${money(core.constant_mix_benchmark)} of actual R8 revenue versus ${money(core.revenue)} observed—${money(core.constant_mix_difference)} above that composition benchmark. ${esc(s.benchmark_basis)}`))+
  `<div class="review-grid seg-evidence-grid">${panel('Revenue mix: where priorities strengthened or weakened','Percentage points relative to R0; zero means the original mix was retained.',`<div id="segment-mix-chart">${historyLine('Revenue mix change from R0 · percentage points',rounds,[s3,s6,support,other].map((x,i)=>series(x.label,x.history.map(p=>100*(p.mix-x.initial_mix)),['#0891b2','#d97706','#7c3aed','#64748b'][i])),v=>fixed(v,1)+' pp',false)}</div>`)}${panel('Growth was a portfolio result','Shares of the total R0→R8 increases; not allocation of spend or profit.',`<div id="segment-growth-chart">${bars(s.groups.map(x=>({label:x.label.split(' · ')[0],values:[100*x.growth_share,100*x.clv_growth_share]})),{title:'Portfolio contribution to revenue and aggregate CLV growth',format:v=>fixed(v,1)+'%',series:['Revenue increase','Aggregate CLV increase']})}</div>${note(`Targets supplied ${pct(core.growth_share)} of revenue growth and ${pct(core.clv_growth_share)} of CLV growth. S1 alone supplied ${pct(other.growth_share)} and ${pct(other.clv_growth_share)}, despite sitting outside the stated priorities.`)}`)}</div>`+
 panel('2 · What worked—and what each priority needs next','Commercial outcomes support a differentiated verdict, not a single win/lose label.',
 `<div class="seg-priority-grid">`+
 `<article><h3>S3 first · keep the differentiated proposition</h3><p><strong>Good:</strong> revenue grew ${pct(s3.revenue_growth)} to ${money(s3.revenue)}, adding ${money(s3.incremental_revenue)}; aggregate CLV grew ${pct(s3.clv_growth)}. S3 has the highest Brand preference (${fixed(segment('SEGMENT 3').preferences.BRAND,2)}) and strong shopping-experience preference (${fixed(segment('SEGMENT 3').preferences['SHOPPING EXPERIENCE'],2)}). Brand was top two in ${review.brand_top_two_rounds.length}/8 scored rounds.</p><p><strong>Improve:</strong> Experience reached #1 only in R8 (1/8 rounds); Brand was outside the top two in R1/R2. Deliver both parts of the promise throughout the run, not only at the endpoint. S3 lost just ${num(-s3.mix_change_pp)} pp of mix: the case for keeping it first is stronger than the case for declaring it a failed target.</p></article>`+
  `<article><h3>S6 second · extend Experience with credible value</h3><p><strong>Good:</strong> S6 added ${money(s6.incremental_revenue)}, grew revenue ${pct(s6.revenue_growth)} and aggregate CLV ${pct(s6.clv_growth)}. Revenue mix gained ${num(s6.mix_change_pp)} pp. Its Low Price / Experience profile offers growth beyond S3 without requiring Brand to matter equally to both segments.</p><p><strong>Improve:</strong> pair service and shopping-experience delivery with credible value. Low Price met fair value in all 8 scored rounds, but Experience led only in R8. S6 revenue grew ${pct(s6.phases[2].growth)} over R6–R8 while losing ${num(-s6.phases[2].mix_change_pp)} pp of mix. Preserve the value proposition as markups rise; observed growth does not identify willingness to pay or segment margins. Frictionless remains a company-wide safeguard, not an S6-specific acquisition gate.</p></article>`+
  `<article><h3>S2 / S4 / S5 · protect the supporting portfolio</h3><p><strong>Good:</strong> together they finish at ${money(support.revenue)}, ${pct(support.mix)} of sales. S4 grew ${pct(s4.revenue_growth)} and gained ${num(s4.mix_change_pp)} pp of mix; S5 grew ${pct(s5.revenue_growth)} despite losing mix.</p><p><strong>Improve:</strong> S2 lost ${num(-s2.mix_change_pp)} pp and its revenue fell ${pct(-s2.phases[1].growth)} during R2–R6. S5’s convenience/Experience needs differ from S6’s value/Experience profile. Maintain separate scorecards rather than treating the supporting portfolio as one homogeneous segment or assuming its margins are superior.</p></article>`+
 `<article><h3>S1 · recognize an unplanned growth engine</h3><p><strong>Good:</strong> ${money(other.revenue)} revenue and ${money(other.clv)} aggregate CLV make S1 the largest final pool; revenue grew ${pct(other.revenue_growth)}. Its mix gained ${num(other.mix_change_pp)} pp.</p><p><strong>Improve:</strong> report and protect this business rather than attributing all gains to the stated targets. Investigate whether service, online and assortment delivery meet S1’s needs. Size and growth justify investigation—not an automatic switch to S1 as the primary acquisition target without margin, retention and acquisition-cost evidence.</p></article></div>`)+
  panel('3 · Timing: early mix gains narrowed during late recovery',esc(s.phase_basis),
  `<div id="segment-phase-chart">${bars(phaseLabels.map((label,i)=>({label,values:[100*core.phases[i].per_round_growth,100*s.phases[i].per_round_growth]})),{title:'Target versus company revenue growth per round by execution window',format:v=>fixed(v,1)+'%',series:['S3 + S6','Company'],palette:['#7c3aed','#64748b']})}</div>`+
  `<p>Target revenue grew ${pct(targetMiddle)} over R2–R6, then ${pct(targetLate)} over R6–R8. The late target pace was ${pct(core.phases[2].per_round_growth)} per round versus the company’s ${pct(s.phases[2].per_round_growth)}. Target mix fell from ${pct(core.history.find(x=>x.round===6).mix)} at R6 to ${pct(core.mix)} at R8, but remained above R0. S6’s late pace (${pct(s6.phases[2].per_round_growth)}) was below S3’s (${pct(s3.phases[2].per_round_growth)}). Absolute recovery and mix improvement are different tests.</p>`+
 `<details><summary>Per-round growth by segment and window</summary>${table(['Segment',...phaseLabels],s.rows.map(x=>[esc(x.label),...x.phases.map(p=>pct(p.per_round_growth))]))}</details>`)+
 panel('4 · Actions: the differentiated offer outpaced service execution','Submitted decisions, reported capabilities and company-wide scores. Co-movement is evidence of consistency or tension, not causal attribution.',
 `<div class="review-grid seg-evidence-grid"><div id="segment-spend-chart">${historyLine('Submitted customer-facing spending · dollars per round',rounds,[series('Service',spendSeries('service'),'#0891b2'),series('Shopping experience',spendSeries('experience'),'#7c3aed'),series('Online',spendSeries('online'),'#d97706'),series('Analytics · multiplier',spendSeries('analytics'),'#64748b',true)],money,false)}</div><div id="segment-capability-chart">${historyLine('Reported customer capabilities · positions, not dollars',rounds,[series('Service',positionSeries('CUSTOMER SERVICE'),'#0891b2'),series('Shopping experience',positionSeries('SHOPPING EXPERIENCE'),'#7c3aed'),series('Online',positionSeries('ONLINE INVEST'),'#d97706')],num,false)}</div></div>`+
 table(['Observed action','Delivery / result','Strategic reading'],[
 ['R2→R6: service spending '+money(at(2).decisions.service)+' → '+money(at(6).decisions.service)+'; experience '+money(at(2).decisions.experience)+' → '+money(at(6).decisions.experience)+'.',
 'Service position 2.7 → 1.5; Experience score 5.8 → 4.8. Target revenue grew '+pct(targetMiddle)+' across four rounds.',
 'The Brand/Experience promise was not matched by reliable service. Protect delivered service capability rather than treating ambience spending as a substitute.'],
 ['R6→R8: service '+money(at(6).decisions.service)+' → '+money(at(8).decisions.service)+'; experience '+money(at(6).decisions.experience)+' → '+money(at(8).decisions.experience)+'.',
  'Service position 1.5 → 3.0; Experience 4.8 → 6.6 (#1). S3+S6 revenue rose '+pct(targetLate)+'.',
 'Late repair coincided with recovery. Quality, stores, assortment and peers also changed; it cannot establish the incremental return on service spend.'],
 ['R6→R8: online '+money(at(6).decisions.online)+' → '+money(at(8).decisions.online)+'; analytics '+money(at(6).decisions.analytics)+' → '+money(at(8).decisions.analytics)+'.',
 'Online position 1.3 → 0.9; Frictionless 2.9 → 3.9, still 0.7 below the R8 floor of 4.6.',
 'Analytics multiplies online/shopping-experience investment; it is not standalone service demand or a replacement for online delivery. A larger analytics budget alone did not preserve online position.'],
 ['R2→R6: stores 236 → 190; R6→R8: 190 → 250. Higher-cost breadth settings 50 → 40 → 50.',
 'Retail position 1.7 → 1.3 → 1.8. S2 revenue declined '+pct(-s2.phases[1].growth)+' in the middle window, then recovered '+pct(s2.phases[2].growth)+' late.',
 'Contraction and restoration are consistent with pressure and recovery in access/breadth-oriented segments. They do not identify a store-count or assortment effect on S2.'],
 ['Quality setting 7 at R2 → 8 at R6 → 10 at R8; higher-cost depth 10 → 15 → 18.',
 'Brand 4.1 → 5.0 → 6.0; top-two status restored from R3. Low Price stayed above each round’s fair value.',
 'Brand differentiation and value parity were delivered, but these company-wide successes did not offset the service/convenience gap. No separate quality, depth or markup effect is identified.']
 ].map(row=>row.map(x=>wrap(esc(x)))),'final-prose')+
 `<details><summary>Experience, Brand and the convenience safeguard · all rounds</summary><div class="review-grid">${historyLine('Reported Brand and Experience scores',rounds,[series('Brand',scoreSeries('BRAND'),'#7c3aed'),series('Experience',scoreSeries('EXPERIENCE'),'#0891b2')],num,false)}${historyLine('Frictionless versus each round’s exported fair value',rounds,[series('Frictionless',scoreSeries('FRICTIONLESS'),'#d97706'),series('Exported fair value',h.map(x=>x.quadrants.FRICTIONLESS.fair_value),'#64748b',true)],num,false)}</div></details>`)+
 panel('5 · Better strategy discipline: keep the order, make delivery testable','Retrospective improvements—not a new-round budget or a claim of optimal allocation.',
 table(['Priority','Keep','Improve / measurement'],[
 ['S3 first','Brand + Experience differentiation; strong revenue and customer-equity growth.','Track Brand top-two and Experience leadership together with service delivery every round. Compare S3 growth and mix with company growth; a small mix decline is not enough to reject a fit-led target.'],
  ['S6 second','Experience/value adjacency and observed revenue and CLV mix gains.','Deliver Experience consistently while holding Low Price at fair value. Monitor S6 mix and contribution as markups change; retain Frictionless parity as a company-wide safeguard.'],
  ['S2 / S4 / S5 supporting','A base that supplied '+pct(support.growth_share)+' of revenue growth.','Use separate scorecards for S2 defense, S4 adjacency and S5 convenience/Experience delivery. Obtain segment contribution and buyer/retention data before reallocating acquisition effort.'],
  ['S1 outside priorities','Recognize its large realized contribution.','Explain its source of growth and cost to serve before promoting or deprioritizing it. Do not relabel S1 gains as proof of the S3/S6 acquisition strategy.']
 ].map(row=>row.map(x=>wrap(esc(x)))),'final-prose'))+
 `<details class="panel"><summary>Supporting evidence · needs, population and full trajectories</summary><p class="review-copy">Raw R8 need intensities—not customer percentages or fitted utilities. S3’s Brand/Experience fit is distinct from S2’s breadth/retail needs. Population is market size, not our buyers; revenue per population member is not customer monetization.</p>`+
 table(['Segment',...needKeys],s.rows.map(x=>[esc(x.label),...needKeys.map(k=>heat(segment(x.ids[0]).preferences[k]||0))]),'heat-table')+
 table(['Segment','Market population growth R0→R8','Company revenue growth'],s.rows.map(x=>[esc(x.label),pct(segment(x.ids[0]).population_growth),pct(x.revenue_growth)]))+
 `<label for="segment-analysis-metric">Trend measure</label><select id="segment-analysis-metric">${[['revenue','Company revenue'],['clv','Aggregate CLV'],['size','Market population']].map(([k,l])=>`<option value="${k}" ${k===segmentAnalysisMetric?'selected':''}>${l}</option>`).join('')}</select><div id="segment-analysis-chart">${segmentAnalysisChart()}</div></details>`+
 note('Evidence boundary: revenue mix is within Getchell’s, not segment market share. Aggregate CLV is customer equity, not per-customer value or realized profit. Company scores are not segment scores. No segment margin, acquisition cost, buyer count, retention or competitor segment sales is available; no causal ROI, optimal target ranking or lost-sales estimate is claimed. Decisions and results retain their supplied round labels; execution windows are descriptive, not verified simulator lags.')+(embed?'':sources());
}

function finalValuePanel(v){return panel('Final market-value model','Final equation · modeling method · full-sample performance.',`<p id="market-value-equation" class="kahn-stage-equation"><strong>${esc(v.equation)}</strong></p><p class="review-copy">${esc(v.method)}</p>`+
 `<div class="cards">${card('FITTED MAPE',fixed(v.fitted_mape*100,2)+'%','All '+v.observations+' financial snapshots')}${card('LOG-VALUE R²',fixed(v.r_squared,4),'In-sample explanatory fit')}${card('VALUE RMSE',money(v.rmse),'Dollar-scale residuals')}${card('FINAL FITTED VALUE',money(v.predictions.at(-1).fitted),'Actual '+money(v.predictions.at(-1).actual))}</div>`+
 `<div class="fit-two"><div>${historyLine('Actual versus fitted market value · R0–R8',v.predictions.map(p=>p.round),[{label:'Reported actual',values:v.predictions.map(p=>p.actual),color:'#7c3aed'},{label:'Full-sample fitted',values:v.predictions.map(p=>p.fitted),color:'#0891b2',dashed:true}],money,false)}</div>${fitScatter(v.predictions,money,'#7c3aed',{label:'Market value actual versus fitted'})}</div>`+
 `<details><summary>Actual / fitted / errors</summary>${table(['Round','Actual','Fitted','Error'],v.predictions.map(p=>['R'+p.round,money(p.actual),money(p.fitted),signed(p.error_pct,pct)]))}</details>`+
 `<details><summary>Model comparison and secondary robustness check</summary>${table(['Fixed-penalty specification','Full-sample MAPE','Hide-one MAPE'],v.comparison.map(c=>[esc(c.name),pct(c.fitted_mape),pct(c.hide_one_mape)]))}<p>Final model: three finance predictors, not fifteen free decision coefficients. The model comparison uses the same nine snapshots and fixed λ=0.01. Hide-one refits the fixed specification; it is not a forecast or selection-adjusted external validation.</p></details><p class="review-copy">${esc(v.boundary)}</p>`);}
marketValueAnalysis=function(embed=false){if(!data.final_review)return priorMarketValueAnalysis();const a=data.history_analysis,ka=a.market_value_analysis,v=ka.value,k=ka.kahn,last=a.history.at(-1);
 return (embed?'':head('FINAL MODEL · R0–R8 FINANCIALS','Market value analysis','The final explanatory model, how it was fitted and how well it describes the full history. Detailed diagnostics are optional.',finalDownload('/market-value-report')))+
 `<div class="cards">${card('REPORTED MARKET VALUE',money(last.market_value),'Final R8 result')}${card('EXPERIENCE / BRAND RANK','#1 / #1','Original differentiators achieved')}${card('FRICTIONLESS SHORTFALL',num(last.quadrants.FRICTIONLESS.target_gap),'3.9 vs exported fair value 4.6')}${card('FINANCIAL SNAPSHOTS',v.observations,'Eight scored rounds + R0 baseline')}</div>`+
 finalValuePanel(v)+
 panel('Final Kahn score models','Eight scored rounds R1–R8; fitted versus reported is plotted for every quadrant.',`<div class="kahn-fit-grid">${k.models.map(m=>`<div class="kahn-fit-card"><div class="eyebrow">${esc(m.quadrant)}</div><div class="kahn-fit-score">MAE ${fixed(m.mae)} · R² ${fixed(m.r_squared)}</div><p>${esc(m.inputs)}</p>${m.level_equation?`<p><strong>${esc(m.level_equation)}</strong></p>`:''}${fitScatter(m.predictions,v=>num(v),'#5338a7',{label:m.quadrant+' actual versus fitted',width:330,height:235})}<p class="kahn-stage-equation">${esc(m.equation)}</p><p>Persistence MAE ${fixed(m.persistence_mae??0)}${m.hide_one_mae!==undefined?` · hide-one ${fixed(m.hide_one_mae)}`:''}</p></div>`).join('')}</div><p class="review-copy">${esc(k.method)} Low Price is nearly flat (observed range 0.2), so its R² is sensitive; the peer-relative specification and scatter should be read with its small absolute error.</p><details><summary>All score and position equations · fifteen-input review</summary>${k.models.map(m=>`<p class="kahn-stage-equation">${esc(m.equation)}</p>`).join('')}${k.position_equations.map(p=>`<p class="kahn-stage-equation">${esc(p.equation)}</p>`).join('')}<p>Relative spending = own submitted spending / same-round exported industry average. Prior positions are from the previous reported round. Quality is one series because private/national settings are identical; assortment and private mix are simple averages. Frictionless and Experience add fitted service and online/experience positions.</p><p>All 15 distinct decisions were screened. The unrestricted 15-input Frictionless fit has training MAE ${fixed(k.all_input_screen_mae)}, but 15 slopes plus an intercept on eight scores cannot establish independent effects. It is not the selected mechanism. ${esc(k.boundary)}</p></details>`)+
 note('Interpretation: earnings growth and financing conditions describe the valuation recovery well. The model does not certify that higher marketing spend caused the value increase or reproduce the simulator’s max(DCF, customer/brand value, liquidation) calculation.')+(embed?'':sources());};

waccImpactAnalysis=function(embed=false){if(!data.final_review)return priorWaccImpactAnalysis();const a=data.wacc_analysis,m=a.model,h=a.history,last=h.at(-1),first=h[0];
 return (embed?'':head('UPDATED FINAL MODEL · R0–R8','WACC impact analysis','Final financing equation and performance. Decision impacts remain indirect through earnings, credit and funding—not sixteen causal WACC coefficients.',finalDownload('/wacc-report')))+
 `<div class="cards">${card('FINAL REPORTED WACC',num(last.wacc)+'%',signed(last.wacc-first.wacc)+' pp since R0')}${card('FITTED MAE',fixed(m.fitted_mae_pp)+' pp','All '+m.observations+' snapshots')}${card('R²',fixed(m.r_squared,4),'Full-sample fit')}${card('FINAL DEBT',money(last.debt),money(first.debt)+' at R0')}</div>`+
 panel('Final WACC model','Final equation · modeling method · performance.',`<p id="wacc-model-equation" class="kahn-stage-equation"><strong>${esc(m.equation)}</strong></p><p class="review-copy">${esc(m.method)}</p><p class="review-copy">Market debt weight = debt / (debt + equity market value). EBIT in the yield uses the same dollar units as market value; the final scale term uses EBIT in $M.</p>`+
 `<div class="fit-two"><div>${historyLine('Actual versus fitted WACC · R0–R8',m.predictions.map(p=>p.round),[{label:'Actual WACC',values:m.predictions.map(p=>p.actual),color:'#7c3aed'},{label:'Full-sample fitted',values:m.predictions.map(p=>p.fitted),color:'#0891b2',dashed:true}],v=>num(v)+'%',false)}</div>${fitScatter(m.predictions,v=>num(v)+'%','#0891b2',{label:'WACC actual versus fitted'})}</div>`+
 table(['Round','Actual WACC (%)','Fitted (%)','Error (pp)'],m.predictions.map(p=>['R'+p.round,num(p.actual),fixed(p.fitted),signed(p.fitted-p.actual,v=>fixed(v))]))+
 `<details><summary>Model alternatives and secondary robustness</summary>${table(['Specification','Fitted MAE (pp)','Hide-one MAE (pp)'],m.comparison.map(c=>[esc(c.name),fixed(c.fitted_mae_pp),fixed(c.loo_mae_pp)]))}<p>Same nine snapshots, fixed λ=0.01. No historical subset-search counts or old search errors are reused. Hide-one is a fixed-specification diagnostic, not proof of out-of-sample forecasting skill.</p></details><p class="review-copy">${esc(m.boundary)}</p>`)+
 panel('What the financial path says','Lower debt did not imply lower reported WACC.',`<p>Debt fell from ${money(first.debt)} to ${money(last.debt)}, but WACC rose from ${num(first.wacc)}% to ${num(last.wacc)}%. Late expansion raised debt again after R6 while WACC settled at 10.0%. Changes in financing mix, credit and earnings must be considered together; market-weight coefficients are not a recommendation to borrow more.</p>`+
 table(['Decision channel','How it can reach WACC'],[['Markup / vendor discipline','Margin, volume and procurement efficiency affect EBIT and interest coverage.'],['Service / experience / online / analytics','Customer execution and immediate expense affect earnings; capitalized investment can add funding needs.'],['Stores / breadth / depth','Reach and choice compete with fixed capital, inventory, liquidity and borrowing needs.'],['Private-brand mix / quality','Differentiation and unit economics can improve or weaken cash generation; neither has an identified direct WACC coefficient.']].map(row=>row.map(text=>`<div class="wrap">${esc(text)}</div>`)),'final-prose'))+
 `<details class="panel"><summary>Inspect any of the 16 actual decision factors</summary><label for="wacc-factor-select">Decision factor</label><select id="wacc-factor-select">${a.factors.map(f=>`<option value="${f.key}" ${f.key===waccFactorKey?'selected':''}>${esc(f.label)}</option>`).join('')}</select><div id="wacc-factor-detail">${waccFactorDetail()}</div></details>`+(embed?'':sources());};
function stpMarketingMap(title,points,{xLabel,yLabel,xMax,yMax,bubbles=false,references=null}){
 const width=640,height=380,left=68,right=34,top=32,bottom=78;
 const x=v=>left+v/xMax*(width-left-right),y=v=>height-bottom-v/yMax*(height-top-bottom);
 const maxSize=Math.max(...points.map(p=>p.size||1));
 let out='';
 if(references)out+=`<rect x="${x(references.x)}" y="${top}" width="${x(xMax)-x(references.x)}" height="${y(references.y)-top}" fill="#e3f7ed"/><text x="${width-right-5}" y="${top+14}" text-anchor="end">Both rank goals</text>`;
 for(let i=0;i<=5;i++){
  const vx=xMax*i/5,vy=yMax*i/5;
  out+=`<line class="grid" x1="${x(vx)}" x2="${x(vx)}" y1="${top}" y2="${y(0)}"/><line class="grid" x1="${left}" x2="${x(xMax)}" y1="${y(vy)}" y2="${y(vy)}"/><text x="${x(vx)}" y="${y(0)+21}" text-anchor="middle">${fixed(vx,bubbles?2:1)}</text><text x="${left-10}" y="${y(vy)+4}" text-anchor="end">${fixed(vy,bubbles?2:1)}</text>`;
 }
 if(references)out+=`<line x1="${x(references.x)}" x2="${x(references.x)}" y1="${top}" y2="${y(0)}" stroke="#087f5b" stroke-dasharray="5 4"/><line x1="${left}" x2="${x(xMax)}" y1="${y(references.y)}" y2="${y(references.y)}" stroke="#087f5b" stroke-dasharray="5 4"/>`;
 points.forEach(p=>{
  const radius=bubbles?16*Math.sqrt(p.size/maxSize):6;
  const labelX=x(p.x)+(p.dx??10),labelY=y(p.y)+(p.dy??-10);
  out+=`<g class="stp-map-point" data-label="${esc(p.label)}"><circle cx="${x(p.x)}" cy="${y(p.y)}" r="${radius}" fill="${p.color}" fill-opacity=".8" stroke="${p.color}" stroke-width="2"><title>${esc(p.label)} · ${esc(xLabel)} ${fixed(p.x,2)} · ${esc(yLabel)} ${fixed(p.y,2)}${bubbles?' · market population '+num(p.size):''}</title></circle><text x="${labelX}" y="${labelY}" text-anchor="${p.anchor||'start'}" class="chart-value">${esc(p.label)}</text></g>`;
 });
 out+=`<text x="${(left+width-right)/2}" y="${height-22}" text-anchor="middle">${esc(xLabel)}</text><text transform="translate(18 ${(top+y(0))/2}) rotate(-90)" text-anchor="middle">${esc(yLabel)}</text>`;
 return svg(title,out,width,height);
}

function finalStpDecision(embed=false){
 const a=data.history_analysis;
 if(!a)return head('STP DECISION','STP decision: how we chose target segments','The historical baseline needed for this review is unavailable.');
  const ids=['SEGMENT 3','SEGMENT 6','SEGMENT 2','SEGMENT 4','SEGMENT 5','SEGMENT 1'];
 const baseline=ids.map(id=>({id,...a.segments.find(x=>x.id===id).history.find(x=>x.round===0)}));
 const total=k=>baseline.reduce((sum,x)=>sum+x[k],0),by=id=>baseline.find(x=>x.id===id);
  const roles=['First · differentiated core','Second · Experience/value target','Supporting · defend the base','Supporting · selective adjacency','Supporting · convenience/Experience','Serve · outside acquisition priorities'];
 const wrap=text=>`<div class="wrap">${esc(text)}</div>`;
 const needs=['BRAND','SHOPPING EXPERIENCE','CUSTOMER SERVICE','ONLINE','RETAIL','LOW PRICE','BREADTH','DEPTH'];
 const maxNeed=Math.max(...baseline.flatMap(x=>needs.map(k=>x.preferences[k]||0)));
  const heat=v=>`<span class="heat-cell" style="background:rgba(124,58,237,${(v/maxNeed*.85).toFixed(2)});color:${v/maxNeed>.6?'#fff':'#35426b'}">${fixed(v,2)}</span>`;
  const segmentColor=id=>id==='SEGMENT 3'?'#7c3aed':id==='SEGMENT 6'?'#0891b2':id==='SEGMENT 1'?'#94a3b8':'#d97706';
 const needMap=stpMarketingMap('R0 segment need map · bubble area is market population',baseline.map(x=>({label:x.id.replace('SEGMENT ','S'),x:x.preferences.BRAND,y:x.preferences['SHOPPING EXPERIENCE'],size:x.size,color:segmentColor(x.id),dy:x.id==='SEGMENT 2'?25:-17})),{xLabel:'Brand preference intensity',yLabel:'Shopping-experience intensity',xMax:.35,yMax:.5,bubbles:true});
 const scores=data.kahn.filter(x=>x.round===0&&x.company!=='FAIR VALUE');
 const companies=[...new Set(scores.map(x=>x.company))];
 const competitorMap=stpMarketingMap('R0 retailer positioning · Brand and Experience ratings',companies.map(company=>({label:company,x:scores.find(x=>x.company===company&&x.quadrant==='BRAND').value,y:scores.find(x=>x.company===company&&x.quadrant==='EXPERIENCE').value,color:company==="GETCHELL'S"?'#7c3aed':'#64748b',dx:company==="GETCHELL'S"?-10:10,dy:['BESTCO','PRICEMART'].includes(company)?21:-10,anchor:company==="GETCHELL'S"?'end':'start'})),{xLabel:'Reported Brand rating',yLabel:'Reported Experience rating',xMax:8,yMax:8,references:{x:a.history[0].quadrants.BRAND.target_threshold,y:a.history[0].quadrants.EXPERIENCE.target_threshold}});
  return (embed?'':head('SEGMENTATION → TARGETING → POSITIONING','STP decision: how we chose target segments','The team-confirmed rationale for S3 first and S6 second, with S2/S4/S5 as supporting business—not a retrospective profit ranking.'))+
  panel('The decision in one sentence','Start with the proposition, then choose the customer fit.',`<p class="seg-verdict">Prioritize S3 for Brand and Experience fit; add S6 for a larger Experience/value pool while maintaining credible Low Price. Continue serving S2/S4/S5 and S1 without treating every segment as an equal acquisition priority.</p><ul class="verdict-list"><li><strong>Segmentation:</strong> distinguish six groups by stated needs, market population and existing company business.</li><li><strong>Targeting:</strong> choose fit before size alone: S3 → S6; supporting S2/S4/S5; continue serving S1.</li><li><strong>Positioning:</strong> a leading shopping experience supported by competitive Brand, fair prices and dependable convenience—not price leadership.</li></ul>`)+
  note('Evidence discipline: this explains the user-confirmed priority order using reported R0 baseline profiles and the simulator’s segment descriptions. It reconstructs the logic, not a timestamped record of every original deliberation or proof that the order was optimal. R8 winners are not used to justify the initial choice. The next tab separately tests execution and results.')+
  panel('Fit versus size: the targeting trade-off','R0 needs on the axes; bubble area represents market population, not Getchell’s buyers or revenue.',`<div id="stp-need-map">${needMap}</div><div class="review-legend"><span><i style="background:#7c3aed"></i>S3 · first</span><span><i style="background:#0891b2"></i>S6 · second</span><span><i style="background:#d97706"></i>S2/S4/S5 · supporting</span><span><i style="background:#94a3b8"></i>S1 · serve</span></div>${note('S3 combines the strongest Brand need with strong shopping-experience need; S6 adds a larger Experience/value pool with weaker Brand intensity. Larger bubbles elsewhere do not automatically offer a better fit. These attribute intensities are not fitted quadrant utilities, demand forecasts or an optimality frontier.')}`)+
 panel('1 · Segment needs: why S3 fits first','R0 raw preference intensities, kept separate rather than combined into a fabricated utility score.',
 `<div id="stp-fit-chart">${bars(baseline.map(x=>({label:x.id.replace('SEGMENT ','S'),values:[100*x.preferences.BRAND,100*x.preferences['SHOPPING EXPERIENCE']]})),{title:'R0 Brand and shopping-experience preference intensities by segment',format:v=>fixed(v/100,2),series:['Brand intensity','Shopping-experience intensity'],palette:['#7c3aed','#0891b2']})}</div>`+
  `<ul class="verdict-list"><li><strong>S3 offers the clearest two-part fit:</strong> Brand intensity ${fixed(by('SEGMENT 3').preferences.BRAND,2)} and shopping experience ${fixed(by('SEGMENT 3').preferences['SHOPPING EXPERIENCE'],2)}. It has the strongest Brand preference of the six groups; the supplied Intro p8 profile identifies Brand / Experience.</li><li><strong>S6 extends Experience through value:</strong> shopping experience ${fixed(by('SEGMENT 6').preferences['SHOPPING EXPERIENCE'],2)} versus Brand ${fixed(by('SEGMENT 6').preferences.BRAND,2)}. Its Low Price / Experience profile calls for credible value alongside service and ambience—not price leadership or an S5-style convenience acquisition gate.</li><li><strong>Need intensity is not market share or purchase probability:</strong> ${fixed(by('SEGMENT 3').preferences.BRAND,2)} does not mean 30% of S3 buyers choose us. No preference-weighted sales or profitability model is inferred.</li></ul>`)+
  panel('2 · Scale: why fit and size must be considered separately','R0 baseline only. Revenue and aggregate CLV are Getchell’s existing business; population is the whole market segment.',
 `<div id="stp-scale-chart">${bars(baseline.map(x=>({label:x.id.replace('SEGMENT ','S'),values:[100*x.size/total('size'),100*x.revenue/total('revenue'),100*x.clv/total('clv')]})),{title:'R0 population share versus company revenue and aggregate-CLV mix',format:v=>fixed(v,1)+'%',series:['Market population share','Company revenue mix','Company aggregate-CLV mix'],palette:['#94a3b8','#7c3aed','#0891b2']})}</div>`+
 note('Each series has its own denominator and sums to 100%. A gap between population share and company mix is a concentration difference—not segment market share, penetration, unmet demand or a customer monetization rate. Population counts the whole market; revenue and CLV describe Getchell’s existing business.')+
 table(['Priority / segment','Market population','Population share','Company revenue','Revenue mix','Aggregate CLV'],baseline.map((x,i)=>[wrap(x.id+' · '+roles[i]),num(x.size),pct(x.size/total('size')),money(x.revenue),pct(x.revenue/total('revenue')),money(x.clv)]))+
  `<p>S6 begins with ${money(by('SEGMENT 6').revenue)} of company revenue and ${money(by('SEGMENT 6').clv)} aggregate CLV versus S3’s ${money(by('SEGMENT 3').revenue)} and ${money(by('SEGMENT 3').clv)}. That adds scale to an Experience-led strategy, but does not make S6 a better Brand fit. S3+S6 together represent ${pct((by('SEGMENT 3').revenue+by('SEGMENT 6').revenue)/total('revenue'))} of R0 company revenue, so supporting the existing base is essential.</p>`)+
  panel('3 · Targeting roles: focus does not mean abandoning other customers','Supporting S2/S4/S5 have different jobs; their grouping does not imply identical needs or a learned profit order.',
 table(['Segment / role','Reason for the role','Implication for actions'],[
  ['S3 · first','Strongest Brand preference and strong Experience fit; smaller starting business than S6.','Coordinate quality/assortment differentiation with service and shopping-experience delivery. Do not mistake a high Brand rating for Experience leadership.'],
  ['S6 · second','Larger starting business and market population than S3; Low Price / Experience profile.','Extend service and shopping experience while keeping value credible. Review markup, volume and margin together; Low Price parity is not a mandate to lead on price.'],
 ['S2 · supporting defense','Existing business with breadth, access and value needs rather than a Brand-led acquisition rationale.','Maintain credible assortment, retail access and value; monitor base erosion separately from target growth.'],
 ['S4 · supporting adjacency','Mixed channel and assortment needs; less concentrated Brand/Experience fit than S3.','Serve selectively where the proposition matches; do not create a third equal acquisition priority without incremental economics.'],
  ['S5 · supporting adjacency','Frictionless / Experience needs; not the team’s secondary target.','Serve existing customers and monitor convenience delivery without misclassifying S5 as the acquisition priority.'],
 ['S1 · serve, not original acquisition priority','Very low Brand and zero shopping-experience intensity in the baseline profile; a different service/online/value mix.','Do not chase population size by diluting the chosen proposition; continue serving the base and investigate its economics.']
 ].map(row=>row.map(wrap)),'final-prose'))+
  panel('4 · Positioning and decision safeguards','The same four objectives used in the executive review.',
 `<ul class="verdict-list"><li><strong>Experience first: rank #1 against the six actual competitors.</strong> Customer service and the shopping environment must both be delivered; our own strongest quadrant is not automatically competitive leadership.</li><li><strong>Brand second: remain within the top two.</strong> Differentiated assortment and quality support the proposition; #1 Brand is not required at the expense of Experience.</li><li><strong>Frictionless and Low Price: at least each round’s exported fair value.</strong> These are safeguards, not leadership targets. Low Price is a customer rating, not proof of an operating-cost advantage.</li><li><strong>Analytics supports online and shopping-experience investment.</strong> It is a multiplier, not standalone service demand or a substitute for delivery capacity.</li></ul>`)+
 panel('Competitive starting point: Brand strength, an Experience gap','R0 retailer ratings are a different scale from segment preference intensities; do not overlay the two maps.',`<div id="stp-competitor-map">${competitorMap}</div><p>Getchell’s began at Brand ${num(a.history[0].quadrants.BRAND.score)} (rank #${a.history[0].quadrants.BRAND.rank}) and Experience ${num(a.history[0].quadrants.EXPERIENCE.score)} (rank #${a.history[0].quadrants.EXPERIENCE.rank}). The R0 Experience leader was at ${num(a.history[0].quadrants.EXPERIENCE.target_threshold)}, a ${num(a.history[0].quadrants.EXPERIENCE.target_gap)}-point gap. That supports making Experience the improvement priority, rather than assuming an existing Brand lead fulfilled the whole proposition.</p>${note('Dashed lines mark the R0 peer thresholds: Brand '+num(a.history[0].quadrants.BRAND.target_threshold)+' to attain a top-two rank and Experience '+num(a.history[0].quadrants.EXPERIENCE.target_threshold)+' to tie the leader. The shaded region meets both at the frozen R0 peer scores; future thresholds move. FAIR VALUE is not a retailer and is excluded. Retailer ratings do not establish ownership of any segment or competitor segment market shares.')}`)+
  panel('Full need profile: what the two-axis map leaves out','R0 raw intensities; color uses one common scale across all six segments and eight attributes. Zero is a reported preference, not missing data.',table(['Segment',...needs],baseline.map(x=>[esc(x.id),...needs.map(k=>heat(x.preferences[k]||0))]),'stp-needs-table')+note('The additional service, online, retail and assortment needs explain why Brand/Experience fit alone is insufficient. S6’s Low Price / Experience profile makes value a key part of the secondary proposition. Frictionless remains a company-wide safeguard; no arbitrary sum of attributes is treated as a segment rating.'))+
 note('Source basis: reported R0 segment histories and preferences, supplied simulator segment profiles (including Intro p8), and the user-confirmed target order. Aggregate CLV is not per-customer CLV or obtainable market value. No segment margin, retention, buyer count or acquisition cost establishes an optimal target ranking. See Customer segmentation analysis for the separate R0→R8 outcome audit.')+(embed?'':sources());
}

function finalVerdictPanels(){
 const r=data.final_review,s=r.segmentation_strategy,f=r.finance;
 const delivery=q=>r.objective_delivery.find(x=>x.quadrant===q);
 const bullet=(lead,evidence)=>`<li><strong>${lead}</strong> ${evidence}</li>`;
 return `<div class="review-grid verdict-grid">`+
 panel('Where we did well','Observed achievements—not causal attribution.',`<ul class="verdict-list">`+
 bullet('We achieved the final differentiation goals.',`Experience finished ${num(delivery('EXPERIENCE').final.score)}, rank #1; Brand ${num(delivery('BRAND').final.score)}, rank #1. Brand met the top-two goal in ${delivery('BRAND').count}/8 scored rounds.`)+
 bullet('We preserved the Low Price safeguard.',`The rating met each round’s exported fair value in ${delivery('LOW PRICE').count}/8 rounds; R8 was 4.7 versus 3.7. A low competitor rank is not a failure of this parity-only objective.`)+
  bullet('Both targets grew, and the supporting portfolio mattered.',`S3/S6 revenue grew ${pct(s.rows[0].revenue_growth)} / ${pct(s.rows[1].revenue_growth)}; their aggregate CLV grew ${pct(s.rows[0].clv_growth)} / ${pct(s.rows[1].clv_growth)}. S2/S4/S5 supplied ${pct(s.groups[1].growth_share)} of total revenue growth.`)+
 bullet('The financial outcome recovered strongly.',`Net income moved from ${money(f.initial_net_income)} to ${money(f.net_income)}; market value reached ${money(f.market_value)}. These are company outcomes, not measured returns on the targeting strategy.`)+
 `</ul>`)+
 panel('Where we fell short','Timing, convenience and segment delivery qualify the final success.',`<ul class="verdict-list">`+
 bullet('Experience leadership came too late.',`The first-priority objective was met in only ${delivery('EXPERIENCE').count}/8 rounds, first in R8. Brand was outside the top two in R1/R2. No scored round met all four objectives (${r.all_objectives_met_rounds.length}/8).`)+
 bullet('Frictionless never reached the required floor.',`Parity was met in ${delivery('FRICTIONLESS').count}/8 rounds; R8 was 3.9 versus 4.6, a 0.7-point miss. Online position fell 1.3 → 0.9 over R6–R8 despite the late service recovery.`)+
  bullet('Combined target gains masked S3 erosion—and S2 defense weakened.',`S3+S6 revenue mix rose ${num(s.groups[0].mix_change_pp)} pp, but S3 lost ${num(-s.rows[0].mix_change_pp)} pp while S6 gained ${num(s.rows[1].mix_change_pp)} pp. S2 lost ${num(-s.rows[2].mix_change_pp)} pp. Combined gains do not prove strong execution in every segment.`)+
 bullet('Higher value did not establish volume leadership or lower WACC.',`Unit share ended at ${pct(f.unit_share)} versus ${pct(f.initial_unit_share)} at R0; WACC ended ${num(f.wacc_change_pp)} pp higher. Late debt increased ${money(f.late_debt_change)} after R6. Segment profitability and causal marketing ROI remain unmeasured.`)+
 `</ul>`)+`</div>`;
}

function toggleReportEvidence(button){
  const sections=[...document.querySelectorAll('.report-detail')],open=sections.some(x=>!x.open);
  sections.forEach(x=>{x.open=open;});
  button.textContent=open?'Collapse detailed evidence':'Expand detailed evidence';
  button.setAttribute('aria-expanded',String(open));
}

function finalCombinedReport(){
  const r=data.final_review,h=data.history_analysis.history,first=h[0],last=h.at(-1),s=r.segmentation_strategy;
  const [core]=s.groups,[s3,s6]=s.rows,rounds=h.map(x=>x.round);
  const detail=(label,content)=>`<details class="report-detail"><summary>${label}</summary><div class="report-detail-body">${content}</div></details>`;
  const section=(id,title,summary,evidence)=>`<section class="report-section report-brief" id="${id}"><h2 class="report-section-title">${title}</h2>${summary}${evidence}</section>`;
  const trend=(id,title,key,format,color)=>`<div id="${id}">${historyLine(title,rounds,[{label:'Reported actual',values:h.map(x=>x[key]),color}],format,false)}</div>`;
  const nav=`<nav class="report-nav" aria-label="Report sections"><a href="#overview">1 · Overview</a><a href="#stp">2 · Strategy</a><a href="#segmentation">3 · Customers</a><a href="#marketvalue">4 · Market value</a><a href="#wacc">5 · WACC</a></nav>`;
  const overview=`<p class="report-lead">Brand and Experience finished #1. Financial performance recovered strongly, but Experience leadership arrived late and Frictionless never reached fair value.</p>`+
    `<div class="cards report-key-metrics">${card('MARKET VALUE',money(last.market_value),money(first.market_value)+' at R0')}${card('CUSTOMER LIFETIME VALUE',money(last.clv),money(first.clv)+' at R0 · '+fixed(last.clv/first.clv,2)+'×')}${card('NET INCOME',money(last.net_income),money(first.net_income)+' at R0')}${card('TARGET REVENUE MIX',pct(core.mix),pct(core.initial_mix)+' at R0 · S3 + S6')}</div>`+
    table(['Objective','R0 baseline','R8 final','Rounds met¹'],['BRAND','EXPERIENCE','LOW PRICE','FRICTIONLESS'].map(q=>{
      const d=r.objective_delivery.find(x=>x.quadrant===q),v=last.quadrants[q];
      return [q==='BRAND'?'Brand · top two':q==='EXPERIENCE'?'Experience · #1':q==='LOW PRICE'?'Low Price · fair value':'Frictionless · fair value',num(first.quadrants[q].score),num(v.score)+' · '+(v.target_met?'Met':'Missed'),d.count+'/8'];
    }))+`<p class="report-caption">¹ R1–R8 only; R0 is the baseline. No scored round met all four objectives.</p>`;
  const stp=`<p class="report-lead">S3 → S6: defend Brand-led differentiation, then grow through Experience and credible value.</p>`+
    `<div class="report-role-grid"><article><h3>S3 · primary</h3><p>Brand + Experience shoppers. Our strongest fit, but a smaller growth pool.</p></article><article><h3>S6 · secondary</h3><p>Experience + Low Price shoppers. Extend the experience proposition without trying to win on price.</p></article></div>`+
    `<p class="report-caption">Keep serving S2/S4/S5 and S1. Frictionless remains a company-wide safeguard, not an S6-specific acquisition gate.</p>`;
  const segmentation=`<p class="report-lead">S6’s mix gains outweighed S3’s decline. Together, the targets grew revenue ${pct(core.revenue_growth)} and supplied ${pct(core.growth_share)} of company revenue growth.</p>`+
    table(['Target','R0 revenue','R8 revenue','Growth','Revenue mix Δ'],[s3,s6,core].map(x=>[x===core?'S3 + S6':x===s3?'S3 · primary':'S6 · secondary',money(x.initial_revenue),money(x.revenue),pct(x.revenue_growth),signed(x.mix_change_pp)+' pp']))+
    `<div id="report-target-mix-chart">${historyLine('S3 + S6 · share of company revenue and aggregate CLV',rounds,[{label:'Revenue mix',values:core.history.map(x=>x.mix),color:'#7c3aed'},{label:'Aggregate-CLV mix',values:core.history.map(x=>x.clv_mix),color:'#0891b2'}],pct,false)}</div>`+
    `<p class="report-caption">Revenue mix: ${pct(core.initial_mix)} → ${pct(core.mix)}. CLV mix: ${pct(core.initial_clv_mix)} → ${pct(core.clv_mix)}. S1 remained the largest final revenue pool; growth was not confined to the targets.</p>`;
  const marketvalue=`<p class="report-lead">Market value reached ${fixed(last.market_value/first.market_value,1)}× the R0 baseline, despite a higher WACC.</p>`+
    trend('report-value-chart','Market value · R0–R8 · dollars','market_value',money,'#7c3aed')+
    `<p>Stronger earnings accompanied the recovery: net income moved from ${money(first.net_income)} to ${money(last.net_income)}, while gross margin rose from ${pct(first.gross_margin)} to ${pct(last.gross_margin)}.</p>`;
  const wacc=`<p class="report-lead">WACC rose ${num(last.wacc-first.wacc)} percentage points. The recovery was not a lower-discount-rate story.</p>`+
    trend('report-wacc-chart','WACC · R0–R8 · percent','wacc',v=>fixed(v,1)+'%','#d97706')+
    `<p>Debt finished below R0 but rose ${money(r.finance.late_debt_change)} after R6 as stores expanded from ${num(r.finance.late_stores)} to ${num(r.finance.stores)}. Expansion increased funding pressure.</p>`;
  return head('FINAL REVIEW · R0 BASELINE → R8','Getchell’s final marketing and finance review','The results and the S3 → S6 strategy. Detailed evidence is optional.',
    `<button type="button" class="button report-evidence-toggle" aria-expanded="false" onclick="toggleReportEvidence(this)">Expand detailed evidence</button><button type="button" class="button" onclick="window.print()">Print / save PDF</button>`)+
    `<p id="report-generated" class="review-copy"></p>`+nav+
    section('overview','1 · Executive overview',overview,detail('Delivery timeline and full executive review',historyOverview(true)))+
    section('stp','2 · Why S3 first, S6 second',stp,detail('Segment needs, market size and competitive fit',finalStpDecision(true)))+
    section('segmentation','3 · Customer segmentation',segmentation,detail('All segments, CLV, execution windows and actions',customerSegmentationAnalysis(true)))+
    section('marketvalue','4 · Market value',marketvalue,detail('Valuation equation, fit diagnostics and Kahn models',marketValueAnalysis(true)))+
    section('wacc','5 · Financing and WACC',wacc,detail('WACC equation, debt history and decision channels',waccImpactAnalysis(true)))+
    `<aside class="report-evidence-note"><strong>How to read the evidence.</strong> R0 is the baseline; R1–R8 are scored rounds. Revenue mix is within Getchell’s, not segment market share. CLV is aggregate customer equity, not per-customer value. Results and fitted equations describe associations—not causal returns or segment profitability. Expand evidence before printing to include it.</aside>`+
    detail('Sources and data definitions',sources());
}
